-- Database Kawasan Rawan Bencana (KRB) Aceh.
-- Grain: kabupaten × jenis bahaya (IRBI 2025) + kawasan bernama + katalog dokumen.
-- Geometry stays in official PVMBG/InaRISK maps — do not store polygon GeoJSON here.
-- Apply after 20260906_cms_domain_tables.sql (is_super_admin).
-- Seed rows generated by scripts/build-krb-aceh.mjs and inlined below.

create table if not exists public.krb_jenis_bahaya (
  kode text primary key,
  label_id text not null,
  label_en text,
  kategori text not null check (kategori in ('hidrometeorologi', 'geologi', 'klimatologi')),
  sumber_otoritatif text,
  updated_at timestamptz not null default now()
);

create table if not exists public.krb_kabupaten (
  kode_kabupaten text primary key,
  kabupaten text not null,
  is_kota boolean not null default false,
  irb_2025 double precision,
  kelas_risiko_2025 text check (kelas_risiko_2025 in ('RENDAH', 'SEDANG', 'TINGGI')),
  irb_2024 double precision,
  ancaman_tertinggi text,
  skor_ancaman_tertinggi double precision,
  kelas_ancaman_tertinggi text,
  jumlah_ancaman_tinggi int not null default 0,
  ancaman_tinggi text[] not null default '{}'::text[],
  latitude double precision,
  longitude double precision,
  sumber text,
  updated_at timestamptz not null default now()
);

create index if not exists krb_kabupaten_kelas_idx
  on public.krb_kabupaten (kelas_risiko_2025);
create index if not exists krb_kabupaten_ancaman_idx
  on public.krb_kabupaten (ancaman_tertinggi);

create table if not exists public.krb_wilayah (
  id text primary key,
  kode_kabupaten text not null references public.krb_kabupaten (kode_kabupaten) on delete cascade,
  kabupaten text not null,
  jenis_bahaya text not null references public.krb_jenis_bahaya (kode) on delete restrict,
  kelas_ancaman text not null check (kelas_ancaman in ('RENDAH', 'SEDANG', 'TINGGI')),
  skor_irbi double precision,
  tahun_acuan int not null default 2025,
  sumber text,
  sumber_url text,
  latitude double precision,
  longitude double precision,
  payload jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  unique (kode_kabupaten, jenis_bahaya)
);

create index if not exists krb_wilayah_jenis_kelas_idx
  on public.krb_wilayah (jenis_bahaya, kelas_ancaman);
create index if not exists krb_wilayah_kabupaten_idx
  on public.krb_wilayah (kabupaten);

create table if not exists public.krb_kawasan (
  id text primary key,
  nama text not null,
  jenis_bahaya text not null references public.krb_jenis_bahaya (kode) on delete restrict,
  zona text not null,
  kabupaten text[] not null default '{}'::text[],
  kode_kabupaten text[] not null default '{}'::text[],
  deskripsi text,
  potensi_bahaya text,
  latitude double precision,
  longitude double precision,
  tahun_acuan int,
  sumber text,
  sumber_url text,
  grain text,
  catatan text,
  payload jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

create index if not exists krb_kawasan_jenis_idx
  on public.krb_kawasan (jenis_bahaya);

create table if not exists public.krb_dokumen (
  id text primary key,
  judul text not null,
  jenis text not null,
  wilayah text,
  kabupaten text,
  tahun_mulai int,
  tahun_akhir int,
  penerbit text,
  status text,
  url text,
  catatan text,
  payload jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

create index if not exists krb_dokumen_jenis_idx
  on public.krb_dokumen (jenis);

alter table public.krb_jenis_bahaya enable row level security;
alter table public.krb_kabupaten enable row level security;
alter table public.krb_wilayah enable row level security;
alter table public.krb_kawasan enable row level security;
alter table public.krb_dokumen enable row level security;

do $$
declare
  t text;
  tables text[] := array[
    'krb_jenis_bahaya',
    'krb_kabupaten',
    'krb_wilayah',
    'krb_kawasan',
    'krb_dokumen'
  ];
begin
  foreach t in array tables loop
    if not exists (
      select 1 from pg_policies
      where schemaname = 'public' and tablename = t and policyname = t || '_select_public'
    ) then
      execute format(
        'create policy %I on public.%I for select to anon, authenticated using (true)',
        t || '_select_public',
        t
      );
    end if;

    execute format('drop policy if exists %I on public.%I', t || '_insert_super_admin', t);
    execute format('drop policy if exists %I on public.%I', t || '_update_super_admin', t);
    execute format('drop policy if exists %I on public.%I', t || '_delete_super_admin', t);

    execute format(
      'create policy %I on public.%I for insert to authenticated with check (public.is_super_admin())',
      t || '_insert_super_admin',
      t
    );
    execute format(
      'create policy %I on public.%I for update to authenticated using (public.is_super_admin()) with check (public.is_super_admin())',
      t || '_update_super_admin',
      t
    );
    execute format(
      'create policy %I on public.%I for delete to authenticated using (public.is_super_admin())',
      t || '_delete_super_admin',
      t
    );
  end loop;
end $$;


