insert into public.krb_kawasan (
  id, nama, jenis_bahaya, zona, kabupaten, kode_kabupaten, deskripsi, potensi_bahaya,
  latitude, longitude, tahun_acuan, sumber, sumber_url, grain, catatan
) values
  ('gunungapi-bur-ni-telong', 'KRB Gunungapi Bur Ni Telong', 'letusan_gunung_api', 'KRB_I_II_III', ARRAY['Bener Meriah']::text[], ARRAY['11.17']::text[], 'Peta Kawasan Rawan Bencana Gunungapi Bur Ni Telong (PVMBG, dirilis 31 Desember 2025) membagi lereng menjadi KRB III (puncak/lereng terdekat), KRB II (lembah sungai), dan KRB I (zona terluar).', 'KRB III: awan panas, lontaran batu pijar, guguran lava, gas beracun. KRB II: awan panas, aliran lava, lahar, guguran batu, hujan abu lebat. KRB I: hujan abu vulkanik dan lahar dingin.', 4.769, 96.821, 2025, 'PVMBG / InfoPublik Komdigi (MC Bener Meriah)', 'https://infopublik.id/kategori/nusantara/953658/pvmbg-rilis-peta-kawasan-rawan-bencana-gunungapi-bur-ni-telong-di-bener-meriah', 'kawasan_bernama', 'Polygon KRB I/II/III tidak disalin ke database — acuan peta resmi PVMBG.'),
  ('gunungapi-seulawah-agam', 'KRB Gunungapi Seulawah Agam', 'letusan_gunung_api', 'KRB_I_II_III', ARRAY['Aceh Besar']::text[], ARRAY['11.06']::text[], 'PVMBG menyusun Peta KRB letusan Seulawah Agam (2007) dalam tiga kategori kawasan. Pos Pengamatan Gunung Api berada di Lambaro Tunong sejak 1997.', 'Aliran lava, lahar, awan panas, hujan debu, dan lontaran batu pijar sesuai zonasi KRB PVMBG.', 5.448, 95.658, 2007, 'PVMBG peta KRB 2007 (dirujuk Ibnu Rusydy / Melek Bencana)', 'https://www.ibnurusydy.com/mengenal-status-dan-kawasan-rawan-bencana-seulawah-agam/', 'kawasan_bernama', 'Koordinat puncak ~5.448 N / 95.658 E, 1810 mdpl — bukan batas poligon KRB.'),
  ('gunungapi-peut-sague', 'KRB Gunungapi Peut Sague (Peut Sangoe)', 'letusan_gunung_api', 'KRB_I_II_III', ARRAY['Pidie','Aceh Tengah']::text[], ARRAY['11.07','11.04']::text[], 'Peta Kawasan Rawan Bencana Gunungapi Peut Sague, Sumatera, Provinsi Nanggroe Aceh Darussalam Tahun 2008, skala 1:50.000 (PVMBG).', 'Zona KRB gunung api sesuai peta PVMBG 2008 (awan panas, lava, lahar, abu).', 4.914, 96.329, 2008, 'PVMBG / Perpustakaan Badan Geologi', 'https://geologi.esdm.go.id/perpustakaan/?p=cite&id=28725&keywords=', 'kawasan_bernama', 'Polygon 1:50.000 tidak diimpor; entri ini adalah katalog peta resmi.'),
  ('sesar-besar-sumatera', 'Sesar Besar Sumatera (Great Sumatran Fault)', 'gempabumi', 'sesar_aktif', ARRAY['Aceh Selatan','Aceh Tenggara','Aceh Timur','Aceh Tengah','Aceh Barat','Aceh Besar','Pidie','Aceh Utara','Simeulue','Aceh Singkil','Bireuen','Aceh Barat Daya','Gayo Lues','Aceh Jaya','Nagan Raya','Aceh Tamiang','Bener Meriah','Pidie Jaya','Banda Aceh','Sabang','Lhokseumawe','Langsa','Subulussalam']::text[], ARRAY['11.01','11.02','11.03','11.04','11.05','11.06','11.07','11.08','11.09','11.10','11.11','11.12','11.13','11.14','11.15','11.16','11.17','11.18','11.71','11.72','11.73','11.74','11.75']::text[], 'IRBI 2025 mencatat Aceh berada di zona tektonik aktif pertemuan lempeng Indo-Australia dan Eurasia, dibelah Sesar Besar Sumatera, sehingga rawan gempa.', 'Gempabumi tektonik darat di sepanjang sesar; likuefaksi di dataran aluvial.', 4.5, 96.5, 2025, 'BNPB IRBI 2025 (Buku IRBI halaman Aceh)', 'https://inarisk.bnpb.go.id/IRBI-2025/files/basic-html/page58.html', 'koridor_geologi', 'Bukan peta sesar resolusi tinggi — grain provinsi.'),
  ('zona-subduksi-aceh', 'Zona subduksi Indo-Australia–Eurasia (pesisir barat Aceh)', 'tsunami', 'megathrust', ARRAY['Simeulue','Aceh Singkil','Aceh Selatan','Aceh Barat Daya','Aceh Barat','Nagan Raya','Aceh Jaya','Aceh Besar','Banda Aceh','Sabang','Subulussalam']::text[], ARRAY['11.09','11.10','11.01','11.12','11.05','11.15','11.14','11.06','11.71','11.72','11.75']::text[], 'IRBI 2025: Aceh di pertemuan lempeng Indo-Australia dan Eurasia. Pesisir barat-selatan menghadap Samudra Hindia — kawasan tsunami 26 Desember 2004.', 'Gempabumi megathrust dan tsunami pesisir.', 4, 95.6, 2025, 'BNPB IRBI 2025', 'https://inarisk.bnpb.go.id/IRBI-2025/files/basic-html/page58.html', 'koridor_geologi', 'Daftar kab/kota pesisir barat berdasarkan geografi pantai, bukan peta inundasi desa.'),
  ('pesisir-utara-timur-tsunami', 'Pesisir utara–timur Aceh (Selat Malaka)', 'tsunami', 'pesisir', ARRAY['Pidie','Pidie Jaya','Bireuen','Lhokseumawe','Aceh Utara','Aceh Timur','Langsa','Aceh Tamiang']::text[], ARRAY['11.07','11.18','11.11','11.73','11.08','11.03','11.74','11.16']::text[], 'Dataran pantai utara–timur yang landai (IRBI 2025). Kelas ancaman tsunami per kab/kota mengikuti IRBI, bukan peta run-up desa.', 'Tsunami dan gelombang ekstrem/abrasi di pesisir Selat Malaka.', 5.1, 97.2, 2025, 'BNPB IRBI 2025', 'https://inarisk.bnpb.go.id/IRBI-2025/files/basic-html/page58.html', 'koridor_pesisir', 'Kelas per kab ada di krb_wilayah jenis tsunami.'),
  ('pegunungan-gayo-bukit-barisan', 'Pegunungan Gayo / Bukit Barisan (kerawanan banjir relatif rendah)', 'banjir', 'dataran_tinggi', ARRAY['Aceh Tengah','Bener Meriah','Gayo Lues']::text[], ARRAY['11.04','11.17','11.13']::text[], 'Analisis SMCE independen (MAPID, April 2026) menilai hanya Aceh Tengah, Bener Meriah, dan Gayo Lues yang indeks kerawanan banjirnya sangat aman hingga aman. Bukan peta KRB resmi BNPB.', 'Banjir relatif lebih rendah; longsor dan letusan (Bur Ni Telong) tetap relevan.', 4.4, 97, 2026, 'MAPID — Analisis Kerawanan Banjir Provinsi Aceh (SMCE/AHP, bukan KRB resmi)', 'https://mapid.co.id/blog/analisis-kerawanan-banjir-dan-alokasi-pusat-siaga-bencana-di-provinsi-aceh', 'analisis_independen', 'Lapisan pelengkap. Kelas banjir resmi per kab tetap dari IRBI 2025 di krb_wilayah.')
on conflict (id) do update set
  nama = excluded.nama,
  jenis_bahaya = excluded.jenis_bahaya,
  zona = excluded.zona,
  kabupaten = excluded.kabupaten,
  kode_kabupaten = excluded.kode_kabupaten,
  deskripsi = excluded.deskripsi,
  potensi_bahaya = excluded.potensi_bahaya,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  tahun_acuan = excluded.tahun_acuan,
  sumber = excluded.sumber,
  sumber_url = excluded.sumber_url,
  grain = excluded.grain,
  catatan = excluded.catatan,
  updated_at = now();

